protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex throws in EF Core 9 Cosmos — manage indexing via Azure portal/Bicep.
    modelBuilder.Entity<Product>().ToContainer("Products");

    // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
    // Preserve the old name so existing documents and direct SQL queries still work.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // EF Core 9 no longer embeds the discriminator in the JSON id property.
    // Preserve "Product|123" format so existing 500K documents remain readable.
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

